<?php
require_once __DIR__ . '/../app/application.php';requireAuthentication('../account/login.php');requirePermission('customers.manage');
try{$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id)throw new InvalidArgumentException('not found');$ids=currentAgencyIds();if(!$ids)$ids=[0];$ph=implode(',',array_fill(0,count($ids),'?'));$document=dbFetchOne("SELECT d.id,d.storage_path,d.mime_type FROM customer_documents d JOIN customers c ON c.id=d.customer_id WHERE d.id=? AND d.archived_at IS NULL AND c.archived_at IS NULL AND c.agency_id IN ($ph)",array_merge([(int)$id],$ids));if(!$document)throw new InvalidArgumentException('not found');deliverAuthorizedProtectedFile($document,'customer-document');}catch(InvalidArgumentException$e){protectedFileNotFound();}
